// 坐禅品第五的句级对应样板。location 为 [章、段、句]，均从 1 开始。
// id 独立于页面元素；original 用来检测拆句或正文变化，texts 必须逐字存在于最终译文。
window.TRANSLATION_MAP = {
  'zc-001': { location: [5, 1, 1], original: '师示众云：“此门坐禅，元不著心，亦不著净，亦不是不动。', texts: ['惠能大师开示众人说：“我这个法门所讲的坐禅，原本不是执着于固守本心，也不是执着于一味看净，更不是枯坐不动。'] },
  'zc-002': { location: [5, 1, 2], original: '若言著心，心元是妄，知心如幻，故无所著也。', texts: ['如果说执着心念，心念原本也是虚妄，了解了心念的虚妄，所以也就没有什么可执迷固守的。'] },
  // 两句原文共同由下面这一句白话解释，允许选中任一句时高亮同一区域。
  'zc-003': { location: [5, 1, 3], original: '若言著净，人性本净；', texts: ['如果说执着于追求本性清净，那么人的本性原本就是清净的；由于虚妄心念的缘故，掩盖遮蔽了自我真如本性，一旦没有了虚妄邪见，本性就又自我清净了。'] },
  'zc-004': { location: [5, 1, 4], original: '由妄念故，盖覆真如，但无妄想，性自清净。', texts: ['如果说执着于追求本性清净，那么人的本性原本就是清净的；由于虚妄心念的缘故，掩盖遮蔽了自我真如本性，一旦没有了虚妄邪见，本性就又自我清净了。'] },
  'zc-005': { location: [5, 1, 5], original: '起心著净，却生净妄，妄无处所，著者是妄。', texts: ['生起执心追求所谓的清净，却又生起对清净本身执着的妄念，', '这种妄念本来是无处着落和无所适从的，一旦清净产生执着之心时，它便有了生起的处所。'] },
  'zc-006': { location: [5, 1, 6], original: '净无形相，却立净相，言是工夫，作此见者，障自本性，却被净缚。', texts: ['清净本来是没有形相的，却给清净设定一个形相，硬说符合这一形相的才是修行的功夫，持这样见解的人，障碍迷惑了自我的本性，其实是被所谓的清净执迷束缚了。'] },

  'zc-007': { location: [5, 2, 1], original: '“善知识！', texts: ['“善知识！'] },
  'zc-008': { location: [5, 2, 2], original: '若修不动者，但见一切人时，不见人之是非善恶过患，即是自性不动。', texts: ['如果修‘不动’行，心不生起，那么看任何人的时候，都对他的是非善恶能视而不见，心念不随之扰动，这就是自我本性真正寂然不动。'] },

  'zc-009': { location: [5, 3, 1], original: '“善知识！', texts: ['“善知识！'] },
  'zc-010': { location: [5, 3, 2], original: '迷人身虽不动，开口便说他人是非长短好恶，与道违背。', texts: ['愚迷的人身体虽然在那里纹丝不动，但一开口就是议论别人的是非长短和好坏，这与修道是正好相违背的。'] },
  'zc-011': { location: [5, 3, 3], original: '若著心著净，即障道也。”', texts: ['这与执着于守心看净一样，也是障碍修道的。”'] },

  'zc-012': { location: [5, 4, 1], original: '师示众云：“善知识！', texts: ['惠能大师开示众人说：“善知识！'] },
  'zc-013': { location: [5, 4, 2], original: '何名坐禅？', texts: ['什么叫坐禅？'] },
  'zc-014': { location: [5, 4, 3], original: '此法门中，无障无碍，外于一切善恶境界，心念不起，名为坐；', texts: ['我这个法门中，没有阻碍，遍达自在，对于一切外在的善恶境界，不起心动念，这叫作坐；'] },
  'zc-015': { location: [5, 4, 4], original: '内见自性不动，名为禅。', texts: ['能识见内在自我本性寂然不动，这叫作禅。'] },
  'zc-016': { location: [5, 4, 5], original: '善知识！', texts: ['善知识！'], occurrences: [2] },
  'zc-017': { location: [5, 4, 6], original: '何名禅定？', texts: ['什么叫禅定？'] },
  'zc-018': { location: [5, 4, 7], original: '外离相为禅，内不乱为定。', texts: ['超离外境外相就是禅，内心不散乱叫作定。'] },
  'zc-019': { location: [5, 4, 8], original: '外若著相，内心即乱。', texts: ['如果执着于外境外相，内心必定散乱。'] },
  'zc-020': { location: [5, 4, 9], original: '外若离相，心即不乱。', texts: ['如果超离外境外相，内心就不散乱。'] },
  'zc-021': { location: [5, 4, 10], original: '本性自净自定，只为见境思境即乱。', texts: ['人的本性原是本自清净，本自安定的，只是因为遇见外境因而思虑执着于外境，所以内心就散乱了。'] },
  'zc-022': { location: [5, 4, 11], original: '若见诸境心不乱者，是真定也。', texts: ['如果能见到一切外境而内心不散乱的，这才是真正的定。'] },

  'zc-023': { location: [5, 5, 1], original: '“善知识！', texts: ['“善知识！'] },
  'zc-024': { location: [5, 5, 2], original: '外离相即禅，内不乱即定。', texts: ['超离外境外相就是禅，内心不散乱就是定。'] },
  'zc-025': { location: [5, 5, 3], original: '外禅内定，是为禅定。', texts: ['外禅内定就是禅定。'] },
  'zc-026': { location: [5, 5, 4], original: '《菩萨戒经》云：我本元自性清净。', texts: ['《菩萨戒经》说：自我本性原本清净。'] },
  'zc-027': { location: [5, 5, 5], original: '善知识！', texts: ['善知识！'], occurrences: [2] },
  'zc-028': { location: [5, 5, 6], original: '于念念中，自见本性清净，自修、自行，自成佛道。”', texts: ['时时刻刻识见自我本性清净，自我修持，自我心行，自然成就佛道。”'] }
};

